mapper.select:
select

from profile_meta_dataset
where 1 = 1

  and status = #{status,jdbcType=INTEGER}


  and dataset_id = #{datasetId,jdbcType=VARCHAR}


  and dataset_name = #{datasetName,jdbcType=VARCHAR}


  and dataset_type = #{datasetType,jdbcType=INTEGER}


  and dataset_desc = #{datasetDesc,jdbcType=VARCHAR}


  and source_type = #{sourceType,jdbcType=INTEGER}


  and datasource_id = #{datasourceId,jdbcType=VARCHAR}


  and table_name = #{tableName,jdbcType=VARCHAR}


  and partition_field = #{partitionField,jdbcType=VARCHAR}


  and partition_format = #{partitionFormat,jdbcType=VARCHAR}


  and entity_id = #{entityId,jdbcType=VARCHAR}


  and entity_field = #{entityField,jdbcType=VARCHAR}


  and instance_status = #{instanceStatus,jdbcType=INTEGER}


  and instance_start_time = #{instanceStartTime,jdbcType=TIMESTAMP}


  and instance_end_time = #{instanceEndTime,jdbcType=TIMESTAMP}


  and instance_msg = #{instanceMsg,jdbcType=INTEGER}


  and owner = #{owner,jdbcType=VARCHAR}


  and creator = #{creator,jdbcType=VARCHAR}


  and modifier = #{modifier,jdbcType=VARCHAR}


  and gmt_create = #{gmtCreate,jdbcType=TIMESTAMP}


  and gmt_modified = #{gmtModified,jdbcType=TIMESTAMP}
